import XCTest

final class LikeFirstTests: XCTestCase {
    func testLikeFirstPost() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15), "app not foreground")

        let buttons = app.buttons.allElementsBoundByIndex
        var labels: [String] = []
        var candidates: [(XCUIElement, CGFloat)] = []
        for b in buttons where b.exists && !b.frame.isEmpty {
            let l = b.label
            labels.append("\(l) @y=\(Int(b.frame.minY)) x=\(Int(b.frame.minX))")
            if (l == "Like" || l.hasPrefix("Like ")) && b.frame.minY > 150 && b.isHittable {
                candidates.append((b, b.frame.minY))
            }
        }
        let summary = labels.joined(separator: " | ")
        guard let first = candidates.min(by: { $0.1 < $1.1 })?.0 else {
            XCTFail("no like button found. buttons: \(summary)")
            return
        }
        first.tap()
        sleep(2)
        XCTFail("TAPPED label=\(first.label) frame=\(first.frame) candidates=\(candidates.count) buttons: \(summary)")
    }
}

