#import <XCTest/XCTest.h>

@interface LikeFirstTests : XCTestCase
@end

@implementation LikeFirstTests

- (void)testLikeFirstPost {
    XCUIApplication *app = [[XCUIApplication alloc] initWithBundleIdentifier:@"xyz.blueskyweb.app"];
    [app activate];
    XCTAssertTrue([app waitForState:XCUIApplicationStateRunningForeground timeout:15], @"app not foreground");

    NSArray<XCUIElement *> *buttons = [app.buttons allElementsBoundByIndex];
    NSMutableString *summary = [NSMutableString string];
    XCUIElement *best = nil;
    CGFloat bestY = CGFLOAT_MAX;
    int count = 0;
    for (XCUIElement *b in buttons) {
        CGRect f = b.frame;
        NSString *l = b.label ?: @"";
        [summary appendFormat:@"[%@ y=%d x=%d] ", l, (int)f.origin.y, (int)f.origin.x];
        if (([l isEqualToString:@"Like"] || [l hasPrefix:@"Like "]) && f.origin.y > 150) {
            count++;
            if (f.origin.y < bestY) {
                bestY = f.origin.y;
                best = b;
            }
        }
    }
    if (best == nil) {
        XCTFail(@"no like button found. buttons: %@", summary);
        return;
    }
    NSString *tapped = [NSString stringWithFormat:@"%@ frame=%@ candidates=%d", best.label, NSStringFromCGRect(best.frame), count];
    [best tap];
    [NSThread sleepForTimeInterval:2];
    XCTFail(@"TAPPED %@ | buttons: %@", tapped, summary);
}

@end

